import { useEffect, useState } from 'react';
import api from '../api';

function Feed() {
  const [posts, setPosts] = useState([]);
  const [content, setContent] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [postType, setPostType] = useState('ARTICLE');

  // TEMP: later this will come from login/session
  const userRole = 'ALUMNI'; // change to STUDENT to test
  const userId = 1;

  useEffect(() => {
    fetchFeed();
  }, []);

  const fetchFeed = async () => {
    const res = await api.get('/feed');
    setPosts(res.data);
  };

  const handleCreatePost = async () => {
    if (!content) return alert('Content required');

    await api.post('/post', {
      post_type: postType,
      content,
      image_url: postType === 'IMAGE' ? imageUrl : null,
      created_by: userId
    });

    setContent('');
    setImageUrl('');
    fetchFeed();
  };

  return (
    <div className="feed-container">
      <h2>Feed</h2>

      {/* CREATE POST (ALUMNI ONLY) */}
      {userRole === 'ALUMNI' && (
        <div className="feed-card">
          <h4>Create Post</h4>

          <select
            value={postType}
            onChange={(e) => setPostType(e.target.value)}
          >
            <option value="ARTICLE">Article</option>
            <option value="IMAGE">Image</option>
          </select>

          <textarea
            placeholder="Write something..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
          />

          {postType === 'IMAGE' && (
            <input
              placeholder="Image URL"
              value={imageUrl}
              onChange={(e) => setImageUrl(e.target.value)}
            />
          )}

          <button onClick={handleCreatePost}>Post</button>
        </div>
      )}

      {/* POSTS LIST */}
      {posts.map((post) => (
        <div key={post.post_id} className="feed-card">
          <p>{post.content}</p>

          {post.image_url && (
            <img
              src={post.image_url}
              alt="post"
              style={{ width: '100%', borderRadius: '12px' }}
            />
          )}

          <small>{post.post_type}</small>
        </div>
      ))}
    </div>
  );
}

export default Feed;
